use ai_platform_local_node::{approvals::OneUseApproval,envelope::{Action,ApprovalVerifier,PlatformVerifier},ledger::Ledger,outbox::{Outbox,Receipt},runner::ReplayGuard,digest};
use serde_json::json;
use std::path::PathBuf;
struct Temp(PathBuf);impl Temp{fn new()->Self{let path=std::env::temp_dir().join(format!("platform-local-test-{}-{}",std::process::id(),ai_platform_local_node::now().to_bits()));std::fs::create_dir(&path).unwrap();Self(path)}}impl Drop for Temp{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
struct Trusted;impl PlatformVerifier for Trusted{fn verify(&self,key:&str,_:&[u8],signature:&str)->bool{key=="test-key"&&signature=="test-signature"}}
fn action()->Action{serde_json::from_value(json!({"action_id":"a","idempotency_key":"i","tenant_id":"t","user_id":"u","session_id":"s","run_id":"r","agent_id":"agent","agent_version":"1","call_id":"c","device_id":"d","envelope_version":1,"capability":"file.read","tool_name":"local_file_read","operation":"file.read","capability_lease_id":"g","resource_refs":["g","a.txt"],"arguments_digest":digest(&json!({})),"target_snapshot_digest":"target","policy_snapshot_digest":"policy","nonce":"n","issued_at":ai_platform_local_node::now()-1.,"expires_at":ai_platform_local_node::now()+60.,"platform_key_id":"test-key","platform_signature":"test-signature","approval":null,"trace_context":null})).unwrap()}
#[test]fn durable_idempotency_unknown_and_hash_chain(){let dir=Temp::new();let path=dir.0.join("ledger.db");let a=action();{let mut ledger=Ledger::open(&path).unwrap();assert!(ledger.begin(&a,&Trusted).unwrap().0);assert!(!ledger.begin(&a,&Trusted).unwrap().0);ledger.transition("a","dispatched",None).unwrap();ledger.transition("a","running",None).unwrap();assert_eq!(ledger.disconnect().unwrap(),vec!["a"]);ledger.verify().unwrap();}let mut ledger=Ledger::open(&path).unwrap();assert_eq!(ledger.get("a").unwrap().unwrap().status,"unknown");assert!(!ledger.begin(&a,&Trusted).unwrap().0);assert!(ledger.transition("a","running",None).is_err());let mut changed=a.clone();changed.tenant_id="other".into();assert!(ledger.begin(&changed,&Trusted).is_err());}
#[test]fn one_use_approval_survives_restart(){let dir=Temp::new();let path=dir.0.join("approval.db");{let verifier=OneUseApproval::open("d".into(),&path,|_,sig|sig=="valid").unwrap();assert!(!verifier.verify_and_consume(b"payload","invalid","nonce"));assert!(verifier.verify_and_consume(b"payload","valid","nonce"));}let verifier=OneUseApproval::open("d".into(),&path,|_,_|true).unwrap();assert!(!verifier.verify_and_consume(b"payload","valid","nonce"));}
#[test]fn receipt_ack_bounds_erasure_and_replay_guard(){let dir=Temp::new();let path=dir.0.join("outbox.db");let mut box_=Outbox::open(&path).unwrap();let r=Receipt{sequence:0,event_id:"e".into(),action_id:Some("a".into()),event_type:"action_terminal".into(),status:Some("succeeded".into()),occurred_at:1.,result_digest:None,error_code:None,summary:None,result:Some(json!({"kind":"file_read","content":"hello"}))};assert_eq!(box_.append(r.clone(),true).unwrap().sequence,1);assert_eq!(box_.append(r,true).unwrap().sequence,1);assert!(box_.acknowledge(2).is_err());box_.acknowledge(1).unwrap();assert!(box_.pending(200).unwrap().is_empty());drop(box_);let db=rusqlite::Connection::open(path).unwrap();let raw:Option<String>=db.query_row("SELECT result_json FROM receipt_events",[],|r|r.get(0)).unwrap();assert!(raw.is_none());let mut guard=ReplayGuard::open(&dir.0.join("replay.db")).unwrap();assert!(guard.reserve("c","n","d").unwrap());assert!(!guard.reserve("c","n","d").unwrap());assert!(guard.reserve("other","n","d").is_err());}
#[cfg(unix)]#[test]fn descriptor_grants_reject_symlink_hardlink_and_revoke(){use ai_platform_local_node::workspace::Grant;use std::os::unix::fs::symlink;let dir=Temp::new();std::fs::write(dir.0.join("good"),b"safe").unwrap();symlink("good",dir.0.join("link")).unwrap();let mut g=Grant::issue("g".into(),&dir.0,"t".into(),"u".into(),&["read"],None).unwrap();assert_eq!(g.read("good",100).unwrap(),b"safe");assert!(g.read("link",100).is_err());std::fs::hard_link(dir.0.join("good"),dir.0.join("hard")).unwrap();assert!(g.read("good",100).is_err());assert!(g.authorize("read","other","u").is_err());g.revoke();assert!(g.authorize("read","t","u").is_err());}
#[test]fn canonical_numeric_payload_matches_python_json(){use ai_platform_local_node::canonical;for(value,expected)in [(1e-7,"1e-07"),(1e20,"1e+20"),(1e15,"1000000000000000.0"),(-0.0,"-0.0"),(0.0001,"0.0001")]{assert_eq!(canonical(&json!(value)),expected);}assert_eq!(canonical(&json!({"z":1,"a":{"β":"值","a":2}})),"{\"a\":{\"a\":2,\"β\":\"值\"},\"z\":1}");}
#[cfg(unix)]#[test]fn signed_write_and_rollback_execute_once(){use ai_platform_local_node::{files::{FileService,MISSING_DIGEST},workspace::Grant,envelope::Approval};let dir=Temp::new();let root=dir.0.join("workspace");std::fs::create_dir(&root).unwrap();let g=Grant::issue("g".into(),&root,"t".into(),"u".into(),&["read","write"],None).unwrap();let files=FileService::new(dir.0.join("rollback")).unwrap();let mut ledger=Ledger::open(&dir.0.join("ledger.db")).unwrap();let approval=OneUseApproval::open("d".into(),&dir.0.join("approval.db"),|_,signature|signature=="approved").unwrap();let mut a=action();a.capability="file.write".into();a.operation="file.write".into();a.tool_name="local_file_write".into();a.target_snapshot_digest=MISSING_DIGEST.into();a.arguments_digest=digest(&json!({"grant_id":"g","relative_path":"a.txt","content_sha256":ai_platform_local_node::sha256(b"hello"),"expected_hash":null}));a.approval=Some(Approval{approval_id:"approval".into(),action_id:a.action_id.clone(),device_id:"d".into(),arguments_digest:a.arguments_digest.clone(),target_snapshot_digest:MISSING_DIGEST.into(),policy_snapshot_digest:a.policy_snapshot_digest.clone(),nonce:"approval-nonce".into(),expires_at:a.expires_at,local_signature:"approved".into()});let first=files.write(&g,"a.txt",b"hello",None,&a,&mut ledger,&Trusted,&approval).unwrap();let second=files.write(&g,"a.txt",b"hello",None,&a,&mut ledger,&Trusted,&approval).unwrap();assert_eq!(first.rollback_ref,second.rollback_ref);assert_eq!(std::fs::read(root.join("a.txt")).unwrap(),b"hello");let mut rollback=action();rollback.action_id="rollback-action".into();rollback.idempotency_key="rollback-idempotency".into();rollback.capability="file.write".into();rollback.operation="file.rollback".into();rollback.resource_refs=vec![first.rollback_ref.clone(),"g".into(),"a.txt".into()];rollback.target_snapshot_digest=first.after_sha256.clone();rollback.arguments_digest=digest(&json!({"rollback_ref":first.rollback_ref,"grant_id":"g","relative_path":"a.txt","expected_current_hash":first.after_sha256}));rollback.approval=Some(Approval{approval_id:"rollback-approval".into(),action_id:rollback.action_id.clone(),device_id:"d".into(),arguments_digest:rollback.arguments_digest.clone(),target_snapshot_digest:rollback.target_snapshot_digest.clone(),policy_snapshot_digest:rollback.policy_snapshot_digest.clone(),nonce:"rollback-nonce".into(),expires_at:rollback.expires_at,local_signature:"approved".into()});files.rollback(&g,&first.rollback_ref,&rollback,&mut ledger,&Trusted,&approval).unwrap();assert!(!root.join("a.txt").exists());ledger.verify().unwrap();}
#[test]fn frozen_python_envelope_bytes_and_hashes(){let fixture:serde_json::Value=serde_json::from_str(include_str!("fixtures/envelope.json")).unwrap();let a:Action=serde_json::from_value(fixture["action"].clone()).unwrap();assert_eq!(ai_platform_local_node::canonical(&a.signed_payload()),fixture["canonical_signed_payload"].as_str().unwrap());assert_eq!(digest(&a.signed_payload()),fixture["envelope_digest"]);assert_eq!(digest(&fixture["arguments"]),fixture["arguments_digest"]);}
#[cfg(target_os="linux")]#[tokio::test]async fn allowlisted_process_runs_with_bounded_redacted_receipt(){use ai_platform_local_node::{processes::{ProcessPolicy,ProcessRunner,ProcessRequest,ProcessControl},workspace::Grant,envelope::Approval};use std::{collections::{HashSet,BTreeMap},os::unix::fs::MetadataExt};let dir=Temp::new();let g=Grant::issue("g".into(),&dir.0,"t".into(),"u".into(),&["read"],None).unwrap();let request=ProcessRequest{argv:vec!["/bin/echo".into(),"hello".into()],grant_id:"g".into(),cwd:".".into(),timeout_seconds:5.,env:BTreeMap::new(),network_policy:"inherit".into()};let runner=ProcessRunner{policy:ProcessPolicy{allowed_executables:HashSet::from([std::path::PathBuf::from("/bin/echo")]),max_output_bytes:3,allow_inherited_network:true,..Default::default()},control:ProcessControl::default()};let mut a=action();a.capability="process.run".into();a.operation="process.run".into();a.resource_refs=vec!["g".into(),".".into()];a.arguments_digest=digest(&request.arguments());let info=g.open_dir(".").unwrap().metadata().unwrap();a.target_snapshot_digest=digest(&json!({"grant_id":"g","cwd":".","device":info.dev(),"inode":info.ino()}));a.approval=Some(Approval{approval_id:"process-approval".into(),action_id:a.action_id.clone(),device_id:"d".into(),arguments_digest:a.arguments_digest.clone(),target_snapshot_digest:a.target_snapshot_digest.clone(),policy_snapshot_digest:a.policy_snapshot_digest.clone(),nonce:"process-nonce".into(),expires_at:a.expires_at,local_signature:"approved".into()});let approval=OneUseApproval::open("d".into(),&dir.0.join("approval.db"),|_,signature|signature=="approved").unwrap();let mut ledger=Ledger::open(&dir.0.join("ledger.db")).unwrap();let result=runner.run(&request,&g,&a,&mut ledger,&Trusted,&approval).await.unwrap();assert_eq!(result.status,"succeeded");assert_eq!(result.stdout,"hel");assert!(result.output_truncated);assert_eq!(ledger.get("a").unwrap().unwrap().result.unwrap()["stdout"],"[REDACTED]");ledger.verify().unwrap();}
